    q1Close: "You sit down with someone you trust, in plain language, and when you stand up everything is finished: the goal calculated, the plans explained honestly (including \"investments go up and down\" and \"you could do this free yourself\"), the account opened by your own hands with guidance, the first automatic monthly contribution set, and reminders arranged. It is the same reason families pay a tax preparer when the IRS forms are free: the form is free — the certainty is what costs. And our market is honest about who this is for: not every parent, but the families around us in Oklahoma City who are underserved today — first-generation and immigrant families, hourly workers, grandparents saving for grandchildren. For them, the fee — paid only when the account truly stands open — is cheaper than years of saving that never started.",
