    q2Lead: "A 529 simply has no loan feature — there is nothing to borrow from — and federal law (IRC §529(b)(5)) bars using any interest in the account as security for a loan. The money comes out in only one way — a withdrawal — requested by the account owner. Here is the whole process, with the two clocks that matter:",
    clock1Title: "Clock 1 — no account-age rule, but each new contribution is held 8 business days",
    clock1Body: "There is no \"account must be a year old\" rule — but the plan does hold every new contribution: under the plan description, a contribution cannot be withdrawn until 8 business days after the plan receives it, and a mailed check takes longer to arrive in the first place. So fund at least a couple of weeks before the bill is due. The withdrawal itself is tax-free if the expense qualifies and it lands in the same calendar year as the payment.",
    clock2Title: "Clock 2 — one withdrawal: plan on days, not minutes",
    clock2Body: "You request the withdrawal online, by phone, or by form; the plan sells the investments and sends the money out — to you, to the student, to the school, or to another third party (a non-qualified withdrawal can be paid only to you or the student). From a request in good order to money in the bank is typically about 5–10 business days end to end — a typical-practice estimate, not a state guarantee. Security holds can stretch it: the plan holds withdrawals for 20 business days after a mailing-address change and 30 calendar days after a banking-information change or an ownership transfer, and a request of $100,000 or more needs a medallion signature guarantee. The plan reports each year's withdrawals on Form 1099-Q, furnished by January 31 after the withdrawal year.",
