    familyHook: "Backpacks packed, lunches made, futures planned — a family should not need a finance degree to give a child a head start.",
    familyBody: "The membership is designed around real family life: one parent joins, the children are covered free, each child gets a 529 college-savings goal the family can actually keep up with, family credit is supported through partner banks, and when a young person finishes school, the Job Promotion board carries them to the goal line — a first job.",
