    laterBadge: "Coming later — not open yet",
    laterNo: "Service 5",
    laterName: "Term Advance",
    laterPoints: ["Coming later", "Not offered at start", "Applications open when the Center switches it on"],
    details: ["The ongoing relationship, opening later: join once, participate every year, covered through the whole education life. When the membership opens, your digital Member Card is issued by the system the moment you subscribe, and carries your member number everywhere in the Center. Until then, the membership form below is a waitlist — leave your name and contact and be invited at opening. 529 Access stands inside this membership — a savings goal for each child, tracking on your dashboard, and reminders to keep contributing, because starting is easy and keeping going is where families drift. You do not have to wait for the membership to start saving: the case door above opens your child's account today. The Center never creates a 529 and never touches 529 money: your money goes from you straight to the state plan, and the guidance is general education, never personal investment advice.", "The board that connects people: employers post openings, members and graduates apply, and the system forwards each application to the employer automatically. Education ends at the goal line — a first job.", "For bigger family needs — a car to reach work, home repairs, education costs — members apply once and the system routes the application to partner banks and credit unions. The Center supports the application; it never lends directly."],
    laterText: "When a term's costs land before payday does, members will apply inside their dashboard; the system will check the application and route it to a partner bank or credit union, which reviews it and makes the decision. Term Advance is built into this system but stays switched off at the start — it opens later, on the Center's word.",
