    familySummary: "Hecho para la familia de la mañana escolar — la imagen",
    familyTitle: "Hecho para la familia de la mañana escolar",
    familyHook: "Mochilas listas, almuerzos hechos, futuros planeados — una familia no debería necesitar un título en finanzas para darle a un niño un buen comienzo.",
    familyBody: "La membresía está diseñada alrededor de la vida familiar real: un padre se une, los niños están cubiertos gratis, cada niño recibe una meta de ahorro universitario 529 que la familia sí puede mantener, el crédito familiar se apoya por medio de bancos socios, y cuando un joven termina la escuela, la bolsa de Promoción de Empleo lo lleva a la meta: un primer empleo.",
