    laterNo: "Servicio 5",
    laterName: "Adelanto por Periodo",
    laterPoints: ["Más adelante", "No se ofrece al inicio", "Las solicitudes abren cuando el Centro lo active"],
    details: ["La relación continua, que abre después: únase una vez, participe cada año, cubierto durante toda la vida educativa. Cuando abra la membresía, su Tarjeta de Miembro digital es emitida por el sistema en el momento en que se suscribe, y lleva su número de miembro a todas partes del Centro. Hasta entonces, el formulario de membresía de abajo es una lista de espera — deje su nombre y contacto y sea invitado en la apertura. El Acceso 529 está dentro de esta membresía — una meta de ahorro para cada niño, seguimiento en su panel y recordatorios para seguir aportando, porque empezar es fácil y seguir es donde las familias se desvían. No tiene que esperar a la membresía para empezar a ahorrar: la puerta del caso de arriba abre hoy la cuenta de su hijo. El Centro nunca crea un 529 y nunca toca el dinero 529: su dinero va de usted directo al plan estatal, y la guía es educación general, nunca asesoría personal de inversión.", "La bolsa que conecta personas: los empleadores publican vacantes, los miembros y graduados solicitan, y el sistema envía cada solicitud al empleador automáticamente. La educación termina en la meta — un primer empleo.", "Para necesidades familiares mayores — un auto para llegar al trabajo, reparaciones del hogar, costos de educación — los miembros solicitan una vez y el sistema envía la solicitud a bancos y cooperativas socias. El Centro apoya la solicitud; nunca presta directamente."],
    laterText: "Cuando los costos de un periodo lleguen antes que el día de pago, los miembros solicitarán dentro de su panel; el sistema revisará la solicitud y la enviará a un banco o cooperativa socia, que la revisa y toma la decisión. El Adelanto por Periodo está integrado en este sistema pero permanece apagado al inicio — abre después, por decisión del Centro.",
