    directBody: "El plan oficial del estado de venta directa — usted lo abre en línea, a su nombre, en minutos.",
    aboutPlan: "Sobre este plan",
    directAbout: "Oklahoma 529 es ofrecido por el Estado de Oklahoma, administrado por su Junta de Fideicomisarios (presidida por el Tesorero del Estado) y gestionado por TIAA-CREF Tuition Financing, Inc. (TFI), una compañía de TIAA. Usted elige entre las opciones de inversión del propio plan y puede configurar aportaciones mensuales automáticas desde su banco. No hay tarifa de apertura ni tarifa mensual o anual de cuenta; las opciones de inversión tienen tarifas anuales basadas en activos de 0.15%–0.36%, y algunos servicios opcionales cuestan extra (por ejemplo, un pago devuelto). Los contribuyentes de Oklahoma pueden deducir aportaciones de hasta $10,000 al año ($20,000 en declaración conjunta), con el exceso trasladable hasta cinco años; las aportaciones hechas hasta la fecha posterior entre el 15 de abril o la fecha de vencimiento de la declaración (sin prórrogas) pueden contar para el año fiscal anterior — y la deducción se recupera si ese dinero se retira después para un fin no calificado. Consulte la descripción del plan y su propia situación fiscal.",
    openOfficial: "Abrir en el sitio oficial de Oklahoma 529",
    howWorks: "Cómo funciona un plan 529",
    source: "Fuente:",
    sourceLink: "Oklahoma 529 — sobre el plan",
    advisorKicker: "El plan de Oklahoma vendido por asesores",
    advisorBody: "El segundo plan del estado, vendido por medio de asesores financieros con licencia — para familias que quieren que un asesor ayude a elegir un portafolio.",
    advisorAbout: "El plan es gestionado por Fidelity Investments y se vende solo por medio de asesores financieros. A diferencia del plan directo, OklahomaDream cobra una tarifa anual de cuenta de $20 (eximible) más una tarifa de administración de 0.20% y cargos de venta según la clase — su asesor puede explicárselos. El Centro no vende este plan y no actúa como su asesor — si quiere asesoría sobre qué portafolio conviene a su familia, esa conversación le corresponde a un asesor con licencia.",
    advisorFeeNote: "Elegir este plan también cambia el caso: los casos vendidos por asesores no tienen tarifa de éxito — el Centro solo da guía general, y cualquier tarifa del asesor pertenece al asesor. ¿No está seguro de qué puerta conviene? Inicie su caso como «aún no estoy seguro» — el sistema registra una solicitud de guía y su caso empieza hoy mismo.",
