    details: ["Mối quan hệ lâu dài, sẽ mở sau: tham gia một lần, tham gia mỗi năm, được bao phủ suốt đời sống giáo dục. Khi tư cách hội viên mở, Thẻ Hội viên số của bạn được hệ thống cấp ngay khi bạn đăng ký, và mang số hội viên của bạn đi khắp Trung tâm. Cho đến lúc đó, biểu mẫu hội viên bên dưới là danh sách chờ — hãy để lại tên và thông tin liên hệ để được mời khi mở. Tiếp cận 529 nằm bên trong tư cách hội viên này — một mục tiêu tiết kiệm cho mỗi trẻ, theo dõi trên trang của bạn, và lời nhắc để tiếp tục đóng góp, vì bắt đầu thì dễ, còn duy trì mới là nơi các gia đình trôi dạt. Bạn không cần chờ tư cách hội viên để bắt đầu tiết kiệm: cửa hồ sơ ở trên mở tài khoản cho con bạn ngay hôm nay. Trung tâm không bao giờ tạo ra một 529 và không bao giờ chạm vào tiền 529: tiền của bạn đi thẳng từ bạn tới chương trình tiểu bang, và hướng dẫn chỉ là giáo dục phổ thông, không bao giờ là tư vấn đầu tư cá nhân.", "Bảng kết nối mọi người: nhà tuyển dụng đăng tin, hội viên và người tốt nghiệp nộp đơn, và hệ thống tự động chuyển mỗi đơn tới nhà tuyển dụng. Giáo dục kết thúc ở vạch đích — công việc đầu tiên.", "Cho những nhu cầu gia đình lớn hơn — một chiếc xe để đi làm, sửa chữa nhà, chi phí giáo dục — hội viên nộp đơn một lần và hệ thống chuyển đơn tới các ngân hàng và hợp tác xã tín dụng đối tác. Trung tâm hỗ trợ đơn; nó không bao giờ tự cho vay."],
