    aboutPlan: "Về chương trình này",
    directAbout: "Oklahoma 529 do Tiểu bang Oklahoma cung cấp, do Hội đồng Quản trị của tiểu bang quản lý (Thủ quỹ Tiểu bang làm chủ tịch), và do TIAA-CREF Tuition Financing, Inc. (TFI), một công ty của TIAA, điều hành. Bạn chọn từ các phương án đầu tư của chính chương trình và có thể thiết lập đóng góp tự động hằng tháng từ ngân hàng của bạn. Không có phí mở tài khoản và không có phí tài khoản hằng tháng hay hằng năm; các phương án đầu tư có phí hằng năm dựa trên tài sản từ 0.15%–0.36%, và một vài dịch vụ tùy chọn tốn thêm phí (ví dụ một khoản thanh toán bị trả lại). Người nộp thuế Oklahoma có thể khấu trừ đóng góp tới $10.000 mỗi năm ($20.000 với tờ khai chung), phần vượt được chuyển tiếp tới năm năm; các khoản đóng góp thực hiện trước ngày muộn hơn trong hai ngày — 15 tháng 4 hoặc ngày đến hạn của tờ khai (không tính gia hạn) — có thể tính cho năm thuế trước — và khoản khấu trừ sẽ bị thu hồi nếu số tiền đó sau này được rút cho mục đích không đủ điều kiện. Hãy kiểm tra bản mô tả chương trình và tình hình thuế của riêng bạn.",
