    advisorAbout: "Chương trình được quản lý bởi Fidelity Investments và chỉ bán qua các cố vấn tài chính. Khác với chương trình trực tiếp, OklahomaDream tính phí tài khoản hằng năm $20 (có thể miễn) cộng phí quản lý 0.20% và phí bán hàng tùy theo hạng — cố vấn của bạn có thể giải thích cho bạn. Trung tâm không bán chương trình này và không đóng vai trò cố vấn của bạn — nếu bạn muốn lời khuyên về danh mục nào phù hợp với gia đình mình, cuộc trò chuyện đó thuộc về một cố vấn được cấp phép.",
    advisorFeeNote: "Chọn chương trình này cũng thay đổi hồ sơ: các hồ sơ qua cố vấn không có phí thành công — Trung tâm chỉ đưa ra hướng dẫn phổ thông, và mọi khoản phí của cố vấn đều thuộc về cố vấn. Chưa chắc cánh cửa nào phù hợp? Hãy bắt đầu hồ sơ với lựa chọn \"chưa chắc chắn\" — hệ thống ghi lại yêu cầu hướng dẫn và hồ sơ của bạn vẫn bắt đầu ngay hôm nay.",
