    clock2Title: "时钟 2 — 一次提款：请按天计算，而不是分钟",
    clock2Body: "您在线、通过电话或表格申请提款；计划出售投资并汇出资金——汇给您、学生、学校或其他第三方（不符合条件的提款只能付给您或学生）。从一份手续齐全的申请到钱到银行，通常总共需要大约 5–10 个工作日——这是典型做法的估计，不是州政府的保证。安全持有可能延长时效：邮寄地址变更后计划会持有提款 20 个工作日，银行信息变更或所有权转移后持有 30 个日历日，$100,000 或以上的申请需要 medallion 签名担保（medallion signature guarantee）。计划通过 1099-Q 表格报告每年的提款，在提款年度后的 1 月 31 日之前提供。",
