    pull: "ພໍ່ແມ່ສ່ວນໃຫຍ່ຕັ້ງໃຈຈະເລີ່ມອອມເງິນເພື່ອການຮຽນຂອງລູກ — ສັກມື້ໜຶ່ງ. ຄອບຄົວທີ່ເລີ່ມໄດ້ແທ້ໆ ແມ່ນຄອບຄົວທີ່ມີຄົນຢູ່ຂ້າງໆ. ຈົ່ງເປັນຄອບຄົວທີ່ເຮັດສຳເລັດ: ນັ່ງແນະນຳຄັ້ງດຽວ, ບັນຊີໜຶ່ງເປີດໄວ້ໃນຊື່ຂອງລູກ, ເລີ່ມຕົ້ນດ້ວຍເງິນພຽງ $25.",
    ctaCase: "ເລີ່ມເຄສ 529",
    ctaCaseSuffix: "ເມື່ອສຳເລັດເທົ່ານັ້ນ",
    ctaHow: "ການເຂົ້າເຖິງ 529 ເຮັດວຽກແນວໃດ",
    statCasesStarted: "ເຄສ 529 ທີ່ເລີ່ມແລ້ວ",
    statCasesCompleted: "ເຄສ 529 ທີ່ສຳເລັດແລ້ວ",
    statWaitlist: "ຢູ່ໃນບັນຊີລໍຖ້າສະມາຊິກ",
