    noncitizen: "ຜູ້ບໍ່ແມ່ນພົນລະເມືອງແຕ່ມີສິດ — ຜູ້ຖືບັດຂຽວ, ຜູ້ລີ້ໄພ, ຜູ້ໄດ້ຮັບການປົກປ້ອງ ແລະ ຄ້າຍຄືກັນ: ແຜນທີ່ເງິນຫຼັກຂອງໜ້ານີ້ ໃຊ້ກັບທ່ານໄດ້. ປະຕູ FAFSA ໃນພາກປະຕູບໍລິການ ເປີດໃຫ້ທ່ານ.",
    note529: "ປະຕູ 529 ເປີດໃຫ້ທຸກຄົນ: ເດັກຄົນໃດກໍເປັນເຈົ້າຂອງຜົນປະໂຫຍດຂອງບັນຊີ 529 ໄດ້, ບໍ່ວ່າວີຊາໃດ — ການອອມຂອງຄອບຄົວບໍ່ຂຶ້ນກັບສະຖານະຄົນເຂົ້າເມືອງ.",
    disclaimer: "ຂໍ້ມູນທົ່ວໄປເທົ່ານັ້ນ — ບໍ່ແມ່ນຄຳແນະນຳດ້ານຄົນເຂົ້າເມືອງ. ກົດລະບຽບເງິນຊ່ວຍຍັງຂຶ້ນກັບໂຮງຮຽນ: ຢືນຢັນກັບຫ້ອງການນັກສຶກສາຕ່າງປະເທດ (DSO) ຂອງມະຫາວິທະຍາໄລກ່ອນສະໝັກ.",
