    billingBody: "ເມື່ອສະມາຊິກເປີດ, ສະມາຊິກຖືບັດສະມາຊິກ, ໃຊ້ການສົ່ງເສີມວຽກ ແລະ ການສະໜັບສະໜູນສິນເຊື່ອຄອບຄົວ, ແລະ ຮັກສາການຕິດຕາມ 529 ພ້ອມການເຕືອນ. ສະມາຊິກຈ່າຍຜ່ານ fintech — ບັດ ຫຼື ໂອນເງິນຜ່ານທະນາຄານຜ່ານຜູ້ໃຫ້ບໍລິການຊຳລະເງິນທີ່ມີໃບອະນຸຍາດ, ກົງເຂົ້າບັນຊີທະນາຄານຂອງບໍລິສັດ — ພ້ອມການຢືນຢັນແບບອັດຕະໂນມັດ, ໃບຮັບເງິນ, ແລະ ການຈັດການຕໍ່ອາຍຸໂດຍລະບົບ. ສະມາຊິກຮັກສາສາມຂັ້ນປະຈຳເດືອນ — Starter $15, Family $25, ແລະ Family Plus $40 — ແລະ ໃບແຈ້ງໜີ້ໃບທຳອິດຖືກສ້າງຂຶ້ນເມື່ອສະມາຊິກເປີດ ແລະ ທ່ານເຂົ້າຮ່ວມ.",
