      llc: "ສູງສຸດ $2,000 ຕໍ່ໃບເສຍພາສາ ສຳລັບວິຊາໃນຊ່ວງໃດຂອງຊີວິດກໍຕາມ — ອ້າງສິດຢູ່ໃນໃບເສຍພາສາຂອງທ່ານ, ຢູ່ໜ້າ IRS.",
