    formSubFounding: "यह केस संस्थापक मूल्य पर शुरू होता है और वह मूल्य बनाए रखता है, भले ही आपका केस खुला रहते संस्थापक मूल्य समाप्त हो जाए।",
    formSubStandard: "यह केस मानक मूल्य पर शुरू होता है — पहले पूरे केस के लिए संस्थापक मूल्य समाप्त हो गया है।",
