    successNoFee: "इस केस पर कोई सफलता शुल्क लागू नहीं होता — सलाहकार द्वारा बेचा गया मार्गदर्शन केवल सामान्य शिक्षा है, और कोई भी सलाहकार शुल्क सलाहकार का होता है।",
    successFeeA: "आप आज कुछ नहीं देते। फ्लैट",
