const DICTS: Record<Lang, Dict> = { en, es, vi, zh, lo, hi };

type LangCtx = { lang: Lang; setLang: (l: Lang) => void; t: Dict };
const Ctx = createContext<LangCtx>({ lang: "en", setLang: () => {}, t: en });

export function LangProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(() => {
    try {
      const v = window.localStorage.getItem("elc-lang");
      return v === "es" || v === "vi" || v === "zh" || v === "lo" || v === "hi" || v === "en" ? v : "en";
    } catch {
      return "en";
    }
  });
  const setLang = (l: Lang) => {
    setLangState(l);
    try {
      window.localStorage.setItem("elc-lang", l);
    } catch { /* storage unavailable */ }
  };
  useEffect(() => {
    try {
      document.documentElement.lang = lang === "zh" ? "zh-Hans" : lang;
    } catch { /* no document in this context */ }
  }, [lang]);
  return <Ctx.Provider value={{ lang, setLang, t: DICTS[lang] }}>{children}</Ctx.Provider>;
}

export function useLang(): LangCtx {
  return useContext(Ctx);
}
